// House register: appliances with their warranty, tradespeople (contacts) and the cost log. Pure helpers, unit tested (register.test.ts).
export type Appliance = {
  id: string; household_id: string; name: string; category: string; brand: string | null; model: string | null; serial: string | null; room: string | null;
  purchased_on: string | null; price_nok: number | null; store: string | null; warranty_until: string | null; manual_url: string | null;
  contact_id: string | null; notes: string | null; created_at?: string;
};
export type Contact = { id: string; household_id: string; name: string; trade: string; company: string | null; phone: string | null; email: string | null; notes: string | null };
export type HouseCost = {
  id: string; household_id: string; title: string; amount_nok: number; spent_on: string; contact_id: string | null; appliance_id: string | null;
  task_id: string | null; item_id: string | null; notes: string | null;
};

export const APPLIANCE_CATEGORIES = ['kitchen', 'laundry', 'heating', 'electronics', 'tools', 'outdoor', 'other'] as const;
export const TRADES = ['plumber', 'electrician', 'carpenter', 'painter', 'roofer', 'chimney', 'hvac', 'locksmith', 'gardener', 'cleaner', 'pest', 'other'] as const;

const pad = (n: number) => String(n).padStart(2, '0');
const isoOf = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const dayNumber = (iso: string) => Math.floor(Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10)) / 86_400_000);
/** Whole days from `from` to `to` (both "YYYY-MM-DD"); negative when `to` is earlier. */
export const daysBetween = (from: string, to: string) => dayNumber(to) - dayNumber(from);

export type Warranty = { kind: 'none' | 'active' | 'soon' | 'expired'; days: number };
export const WARRANTY_SOON_DAYS = 60;

/** Where an appliance stands: no warranty date, running, ending within 60 days, or over (days is until the end, negative once over). */
export function warrantyState(a: Pick<Appliance, 'warranty_until'>, today: string): Warranty {
  if (!a.warranty_until) return { kind: 'none', days: 0 };
  const days = daysBetween(today, a.warranty_until);
  return { kind: days < 0 ? 'expired' : days <= WARRANTY_SOON_DAYS ? 'soon' : 'active', days };
}

/** Warranty ending soonest first (still running before over), then the ones without a date, by name. */
export function sortAppliances<T extends Pick<Appliance, 'name' | 'warranty_until'>>(list: T[], today: string): T[] {
  const rank = (a: T) => { const w = warrantyState(a, today); return w.kind === 'expired' ? 2 : w.kind === 'none' ? 3 : 1; };
  return [...list].sort((a, b) => rank(a) - rank(b) || (a.warranty_until ?? '').localeCompare(b.warranty_until ?? '') || a.name.localeCompare(b.name, 'nb'));
}

/** Appliances whose warranty ends within `within` days (not yet over), soonest first. */
export function warrantiesEnding<T extends Pick<Appliance, 'name' | 'warranty_until'>>(list: T[], today: string, within = 30): (T & { days: number })[] {
  return sortAppliances(list, today).map((a) => ({ ...a, days: warrantyState(a, today).days })).filter((a) => a.warranty_until && a.days >= 0 && a.days <= within);
}

/** Notifications to plan: `daysBefore` days ahead of the end at 09:00, only those still in the future. */
export function warrantyReminders(list: Pick<Appliance, 'id' | 'name' | 'warranty_until'>[], now: Date, daysBefore = 30, max = 3): { id: string; name: string; at: Date; days: number }[] {
  const today = isoOf(now);
  const out: { id: string; name: string; at: Date; days: number }[] = [];
  for (const a of list) {
    if (!a.warranty_until) continue;
    const end = a.warranty_until;
    if (daysBetween(today, end) < 0) continue;
    const y = +end.slice(0, 4), m = +end.slice(5, 7) - 1, d = +end.slice(8, 10);
    let at = new Date(y, m, d - daysBefore, 9, 0, 0, 0);
    if (at.getTime() <= now.getTime()) {
      // already inside the window: one reminder tomorrow morning, as long as the warranty is still running then
      at = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 9, 0, 0, 0);
      if (daysBetween(isoOf(at), end) < 0) continue;
    }
    out.push({ id: a.id, name: a.name, at, days: daysBetween(isoOf(at), end) });
  }
  return out.sort((x, y) => x.at.getTime() - y.at.getTime()).slice(0, max);
}

/** The kept-open facts of an appliance as one line: "Bosch SMV4 · Kitchen". */
export const applianceLine = (a: Pick<Appliance, 'brand' | 'model' | 'room'>): string => [[a.brand, a.model].filter(Boolean).join(' '), a.room].filter(Boolean).join(' · ');

/** "tel:+4712345678" for a phone number written any way, or null when it has too few digits. */
export function telHref(phone: string | null | undefined): string | null {
  const digits = (phone ?? '').replace(/[^\d+]/g, '').replace(/(?!^)\+/g, '');
  return digits.replace(/\D/g, '').length >= 5 ? `tel:${digits}` : null;
}
export const mailHref = (email: string | null | undefined): string | null => (email && /^\S+@\S+\.\S+$/.test(email.trim()) ? `mailto:${email.trim()}` : null);
/** A link someone pasted: only http(s) links are kept (no javascript: and the like); "example.com/manual.pdf" gets https. */
export function safeUrl(raw: string | null | undefined): string | null {
  const v = (raw ?? '').trim();
  if (!v) return null;
  const withScheme = /^[a-z][a-z0-9+.-]*:/i.test(v) ? v : `https://${v}`;
  try { const u = new URL(withScheme); return u.protocol === 'http:' || u.protocol === 'https:' ? u.toString() : null; } catch { return null; }
}

// ---- Costs ------------------------------------------------------------------------------------------------------------------
export type CostEntry = { id: string; source: 'job' | 'extra' | 'purchase'; title: string; amount: number; date: string; contactId: string | null; applianceId: string | null; itemId: string | null; note: string | null };
export type CostEvent = { id: string; task_id: string; done_at: string; cost_nok: number | null; note: string | null };

/** "1 250,50", "1250.5" or "kr 900" as a number; null when it is not a plain non-negative amount. */
export function parseAmount(raw: string): number | null {
  const v = raw.replace(/kr\.?/gi, '').replace(/[\s ]/g, '').replace(',', '.');
  if (!/^\d+(\.\d{1,2})?$/.test(v)) return null;
  return Number(v);
}

/** Everything spent in a year in one list, newest first: the costs written down when finishing recurring jobs, the extra costs logged here,
 *  and the price of appliances bought that year. */
export function buildCosts(opts: { year: number; events: CostEvent[]; taskTitles: Map<string, string>; extras: HouseCost[]; appliances: Pick<Appliance, 'id' | 'name' | 'purchased_on' | 'price_nok'>[] }): CostEntry[] {
  const inYear = (d: string) => d.startsWith(`${opts.year}-`);
  const out: CostEntry[] = [];
  for (const e of opts.events) if (e.cost_nok != null && Number(e.cost_nok) > 0 && inYear(e.done_at)) out.push({ id: `e-${e.id}`, source: 'job', title: opts.taskTitles.get(e.task_id) ?? '', amount: Number(e.cost_nok), date: e.done_at, contactId: null, applianceId: null, itemId: null, note: e.note });
  for (const c of opts.extras) if (inYear(c.spent_on)) out.push({ id: `c-${c.id}`, source: 'extra', title: c.title, amount: Number(c.amount_nok), date: c.spent_on, contactId: c.contact_id, applianceId: c.appliance_id, itemId: c.item_id, note: c.notes });
  for (const a of opts.appliances) if (a.price_nok != null && Number(a.price_nok) > 0 && a.purchased_on && inYear(a.purchased_on)) out.push({ id: `a-${a.id}`, source: 'purchase', title: a.name, amount: Number(a.price_nok), date: a.purchased_on, contactId: null, applianceId: a.id, itemId: null, note: null });
  return out.sort((a, b) => b.date.localeCompare(a.date) || b.amount - a.amount);
}

export function costTotals(entries: CostEntry[]): { total: number; byMonth: number[]; bySource: Record<CostEntry['source'], number> } {
  const byMonth = Array(12).fill(0) as number[];
  const bySource = { job: 0, extra: 0, purchase: 0 };
  let total = 0;
  for (const e of entries) { total += e.amount; byMonth[+e.date.slice(5, 7) - 1] += e.amount; bySource[e.source] += e.amount; }
  return { total, byMonth, bySource };
}

/** Years worth showing: this one, and every year with something in it, newest first. */
export function costYears(dates: string[], thisYear: number): number[] {
  return [...new Set([thisYear, ...dates.map((d) => +d.slice(0, 4)).filter((y) => y > 1990 && y <= thisYear + 1)])].sort((a, b) => b - a);
}

/** What has been logged against each finding of the condition report. */
export function spentByItem(costs: Pick<HouseCost, 'item_id' | 'amount_nok'>[]): Map<string, number> {
  const m = new Map<string, number>();
  for (const c of costs) if (c.item_id) m.set(c.item_id, (m.get(c.item_id) ?? 0) + Number(c.amount_nok));
  return m;
}
